#include <iostream>
#include <string>
#include <sstream>
#include <vector>
#include <cstdint>

using namespace std;

/**
 * Variant 5: Using custom method for reading input and printing output
 */

class NumberTheory {
public:
    class Mod998 {
    public:
        long modulus() {
            return 998244353L;
        }

        void fInv(int n) {
            // Implementation of modular inverse precomputation if needed
            // For simplicity, assuming small n, we can compute inverses on the fly
        }

        long mult(long a, long b) {
            return (a * b) % modulus();
        }

        long add(long a, long b) {
            long res = a + b;
            if (res >= modulus()) res -= modulus();
            return res;
        }

        long subtract(long a, long b) {
            long res = a - b;
            if (res < 0) res += modulus();
            return res;
        }

        long ncr(int n, int r) {
            // Compute nCr modulo modulus
            if (r > n || r < 0) return 0;
            long res = 1;
            for (int i = 1; i <= r; ++i) {
                res = mult(res, smallInv(i));
                res = mult(res, n - i + 1);
            }
            return res;
        }

        long smallInv(int n) {
            // Compute modular inverse of n modulo modulus
            return modInverse(n, modulus());
        }

    private:
        long modInverse(long a, long m) {
            // Extended Euclidean Algorithm
            long m0 = m, t, q;
            long x0 = 0, x1 = 1;
            if (m == 1) return 0;
            while (a > 1) {
                q = a / m;
                t = m;
                m = a % m, a = t;
                t = x0;
                x0 = x1 - q * x0;
                x1 = t;
            }
            if (x1 < 0) x1 += m0;
            return x1;
        }
    };
};

long readLine() {
    string line;
    getline(cin, line);
    return line;
}

int main() {
    string inputLine = readLine();
    stringstream ss(inputLine);
    int n, m;
    ss >> n >> m;

    NumberTheory::Mod998 mod;
    // Precompute inverse if needed
    // For this implementation, inverses are computed on the fly

    long phaseSize = 1;
    long p = 1;
    for (int i = 0; p != 0; i++) {
        long denom = n + m - i;
        long invDenom = mod.smallInv(denom);
        p = mod.mult(p, n - i);
        p = mod.mult(p, invDenom);
        phaseSize = mod.add(phaseSize, p);
        if (i >= n) break; // To prevent infinite loop if p becomes 0
    }

    long answer = 0;
    for (int k = 1; k <= n; k++) {
        long numPhases = mod.mult(m + k, mod.smallInv(k));
        long e = mod.mult(numPhases, phaseSize);
        long term = mod.mult(mod.ncr(n, k), e);
        if (k % 2 == 1)
            answer = mod.add(answer, term);
        else
            answer = mod.subtract(answer, term);
    }

    cout << answer << "\n";

    return 0;
}

